const (
	// PathPrefix is where the API is mounted.
	PathPrefix = "/api"
	_maxBody   = 1 << 20
)

var (
	_ ogen.Handler         = (*Handler)(nil)
	_ ogen.SecurityHandler = (*Handler)(nil)
)

// _readOps need only the read scope; every other operation needs write, so a new
// endpoint is not writable with a read key by accident.
var _readOps = map[ogen.OperationName]bool{
	ogen.ListAccountsOperation:    true,
	ogen.GetAccountOperation:      true,
	ogen.ListCategoriesOperation:  true,
	ogen.ListOperationsOperation:  true,
	ogen.GetOperationOperation:    true,
	ogen.ListPlansOperation:       true,
	ogen.ListRulesOperation:       true,
	ogen.GetRuleOperation:         true,
	ogen.GetRuleSettingsOperation: true,
}

// keyCtx is the context key of the authenticated domain.APIKey.
type keyCtx struct{}

// WithKey returns ctx carrying a key authenticated by the caller, which the API then
// trusts instead of the Authorization header. Only in-process callers, the MCP server,
// can set it.
func WithKey(ctx context.Context, key domain.APIKey) context.Context {
	return context.WithValue(ctx, keyCtx{}, key)
}

// Handler implements ogen.Handler and ogen.SecurityHandler.
type Handler struct {
	svc *service.Services
	log *slog.Logger
}

// New returns the API as an http.Handler to mount at PathPrefix.
func New(svc *service.Services, log *slog.Logger) (http.Handler, error) {
	h := &Handler{svc: svc, log: log}
	srv, err := ogen.NewServer(h, h,
		ogen.WithPathPrefix(PathPrefix),
		ogen.WithErrorHandler(h.errorHandler),
		ogen.WithNotFound(func(w http.ResponseWriter, r *http.Request) {
			h.writeError(r.Context(), w, http.StatusNotFound, ogen.ErrorCodeNotFound,
				"no such endpoint")
		}),
		ogen.WithMethodNotAllowed(func(w http.ResponseWriter, r *http.Request, allowed string) {
			w.Header().Set("Allow", allowed)
			h.writeError(r.Context(), w, http.StatusMethodNotAllowed, ogen.ErrorCodeBadRequest,
				"method not allowed")
		}),
	)
	if err != nil {
		return nil, err
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.Body = http.MaxBytesReader(w, r.Body, _maxBody)
		srv.ServeHTTP(w, r)
	}), nil
}

// HandleBearerAuth authenticates the API key and checks its scope.
func (h *Handler) HandleBearerAuth(
	ctx context.Context, op ogen.OperationName, t ogen.BearerAuth,
) (context.Context, error) {
	want := domain.ScopeWrite
	if _readOps[op] {
		want = domain.ScopeRead
	}
	if key, ok := ctx.Value(keyCtx{}).(domain.APIKey); ok {
		if !key.Scope.Allows(want) {
			return ctx, fmt.Errorf("key scope %q does not allow %s: %w", key.Scope, want, errors.ErrForbidden)
		}
		return ctx, nil
	}
	key, err := h.svc.Auth.AuthenticateAPIKey(ctx, t.Token, want)
	if err != nil {
		return ctx, err
	}
	logger.WithAttrs(ctx, slog.Int64("user_id", key.UserID), slog.Int64("key_id", key.ID))
	return context.WithValue(ctx, keyCtx{}, key), nil
}

// NewError maps domain errors to API errors.
func (h *Handler) NewError(ctx context.Context, err error) *ogen.ErrorStatusCode {
	status, code, msg := classify(err)
	h.logError(ctx, status, err)
	return &ogen.ErrorStatusCode{StatusCode: status, Response: ogen.Error{Code: code, Message: msg}}
}

// errorHandler answers request decoding errors, which bypass NewError.
func (h *Handler) errorHandler(ctx context.Context, w http.ResponseWriter, _ *http.Request, err error) {
	status, code, msg := http.StatusBadRequest, ogen.ErrorCodeBadRequest, err.Error()
	var ogenErr ogenerrors.Error
	if !errors.As(err, &ogenErr) {
		status, code, msg = classify(err)
	}
	if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
		status, msg = http.StatusRequestEntityTooLarge, "request body too large"
	}
	h.logError(ctx, status, err)
	h.writeError(ctx, w, status, code, msg)
}

// logError logs an error answered with status: a server error at error level, a
// forbidden request at warn, as it may be probing, and other client errors at debug.
func (h *Handler) logError(ctx context.Context, status int, err error) {
	switch {
	case status >= http.StatusInternalServerError:
		h.log.ErrorContext(ctx, "api error", slog.Int("status", status), slog.Any("error", err))
	case status == http.StatusForbidden:
		h.log.WarnContext(ctx, "api request rejected", slog.Int("status", status), slog.Any("error", err))
	default:
		h.log.DebugContext(ctx, "api request rejected", slog.Int("status", status), slog.Any("error", err))
	}
}

// writeError writes the JSON Error of every API response that is not an operation's.
func (h *Handler) writeError(
	ctx context.Context, w http.ResponseWriter, status int, code ogen.ErrorCode, msg string,
) {
	e := jx.GetEncoder()
	defer jx.PutEncoder(e)
	resp := ogen.Error{Code: code, Message: msg}
	resp.Encode(e)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if _, err := w.Write(e.Bytes()); err != nil {
		h.log.DebugContext(ctx, "write error response", slog.Any("error", err))
	}
}

// ListAccounts implements ogen.Handler.
func (h *Handler) ListAccounts(ctx context.Context) (*ogen.AccountList, error) {
	// every operation requires a key, so a missing one is a wiring bug; fail closed
	key, ok := ctx.Value(keyCtx{}).(domain.APIKey)
	if !ok {
		return nil, errors.ErrUnauthorized
	}
	accounts, err := h.svc.Accounts.List(ctx, key.UserID)
	if err != nil {
		return nil, err
	}
	out := &ogen.AccountList{Items: make([]ogen.Account, len(accounts))}
	for i, a := range accounts {
		out.Items[i] = toAccount(a)
	}
	return out, nil
}

// CreateAccount implements ogen.Handler.
func (h *Handler) CreateAccount(ctx context.Context, req *ogen.AccountCreate) (*ogen.Account, error) {
	// every operation requires a key, so a missing one is a wiring bug; fail closed
	key, ok := ctx.Value(keyCtx{}).(domain.APIKey)
	if !ok {
		return nil, errors.ErrUnauthorized
	}
	in := domain.AccountInput{
		Name:     req.Name,
		Currency: string(req.Currency),
		Kind:     domain.AccountKind(req.Kind.Or("")),
	}
	if l, ok := req.CreditLimit.Get(); ok {
		var err error
		if in.CreditLimit, err = money.Parse(string(l)); err != nil {
			return nil, fmt.Errorf("credit_limit: invalid decimal: %w", errors.ErrInvalid)
		}
	}
	a, err := h.svc.Accounts.Create(ctx, key.UserID, in)
	if err != nil {
		return nil, err
	}
	out := toAccount(a)
	return &out, nil
}

