// ListOperations implements ogen.Handler.
func (h *Handler) ListOperations(ctx context.Context, req *ogen.OperationQuery) (*ogen.OperationList, error) {
	// every operation requires a key, so a missing one is a wiring bug; fail closed
	key, ok := ctx.Value(keyCtx{}).(domain.APIKey)
	if !ok {
		return nil, errors.ErrUnauthorized
	}
	f, err := fromOperationQuery(req)
	if err != nil {
		return nil, err
	}
	p := pagination.Params{Limit: req.PageSize.Or(0)}
	if c, ok := req.Cursor.Get(); ok {
		cur, err := pagination.ParseCursor(c)
		if err != nil {
			return nil, err
		}
		p.After = cur
	}
	ops, next, err := h.svc.Operations.List(ctx, key.UserID, f, p)
	if err != nil {
		return nil, err
	}
	out := &ogen.OperationList{Items: make([]ogen.Operation, len(ops))}
	for i, op := range ops {
		out.Items[i] = toOperation(op)
	}
	if !next.IsZero() {
		out.NextCursor = ogen.NewOptString(next.String())
	}
	return out, nil
}

