// SplitOperation implements ogen.Handler.
func (h *Handler) SplitOperation(
	ctx context.Context, req *ogen.SplitInput, params ogen.SplitOperationParams,
) (*ogen.SplitResult, error) {
	// every operation requires a key, so a missing one is a wiring bug; fail closed
	key, ok := ctx.Value(keyCtx{}).(domain.APIKey)
	if !ok {
		return nil, errors.ErrUnauthorized
	}
	parts := make([]domain.SplitPart, len(req.Parts))
	for i, p := range req.Parts {
		d, err := money.Parse(string(p.Amount))
		if err != nil {
			return nil, fmt.Errorf("parts[%d].amount: invalid decimal: %w", i, errors.ErrInvalid)
		}
		parts[i] = domain.SplitPart{CategoryID: p.CategoryID, Amount: d, Note: p.Note.Or("")}
	}
	ops, err := h.svc.Operations.Split(ctx, key.UserID, params.ID, parts)
	if err != nil {
		return nil, err
	}
	out := &ogen.SplitResult{Items: make([]ogen.Operation, len(ops))}
	for i, op := range ops {
		out.Items[i] = toOperation(op)
	}
	return out, nil
}

