func classify(err error) (int, ogen.ErrorCode, string) {
	// ogen reports a missing or malformed Authorization header with its own error,
	// before HandleBearerAuth runs
	if errors.Is(err, ogenerrors.ErrSecurityRequirementIsNotSatisfied) {
		return http.StatusUnauthorized, ogen.ErrorCodeUnauthorized, "invalid or missing api key"
	}
	switch {
	case errors.Is(err, errors.ErrInvalid):
		return http.StatusBadRequest, ogen.ErrorCodeBadRequest, err.Error()
	case errors.Is(err, errors.ErrForbidden):
		return http.StatusForbidden, ogen.ErrorCodeForbidden, "key scope does not allow this"
	case errors.Is(err, errors.ErrUnauthorized):
		return http.StatusUnauthorized, ogen.ErrorCodeUnauthorized, "invalid or missing api key"
	case errors.Is(err, errors.ErrNotFound):
		return http.StatusNotFound, ogen.ErrorCodeNotFound, err.Error()
	case errors.Is(err, errors.ErrExists), errors.Is(err, errors.ErrConflict):
		return http.StatusConflict, ogen.ErrorCodeConflict, err.Error()
	default:
		return http.StatusInternalServerError, ogen.ErrorCodeInternal, "internal error"
	}
}

func toAccount(a domain.Account) ogen.Account {
	out := ogen.Account{
		ID:       a.ID,
		Name:     a.Name,
		Currency: ogen.Currency(a.Currency),
		Kind:     ogen.AccountKind(a.Kind),
		Archived: a.Archived,
		Balance:  ogen.Amount(a.Balance.Fixed(a.Currency)),
	}
	if !a.CreditLimit.IsZero() {
		out.CreditLimit = ogen.NewOptAmount(ogen.Amount(a.CreditLimit.Fixed(a.Currency)))
	}
	return out
}

func toCategory(c domain.Category) ogen.Category {
	out := ogen.Category{
		ID:       c.ID,
		Kind:     ogen.CategoryKind(c.Kind),
		Name:     c.Name,
		Archived: c.Archived,
	}
	if c.ParentID != 0 {
		out.ParentID = ogen.NewOptInt64(c.ParentID)
	}
	out.Children = make([]ogen.Category, len(c.Children))
	for i, child := range c.Children {
		out.Children[i] = toCategory(child)
	}
	return out
}

func toOperation(op domain.Operation) ogen.Operation {
	out := ogen.Operation{
		ID:        op.ID,
		Type:      ogen.OperationType(op.Type),
		AccountID: op.AccountID,
		Currency:  ogen.Currency(op.Currency),
		Amount:    ogen.Amount(op.Amount.Fixed(op.Currency)),
		Date:      op.Date,
		Payee:     op.Payee,
		Note:      op.Note,
		Tags:      append([]string{}, op.Tags...),
		CreatedAt: op.CreatedAt.UTC(),
	}
	if !op.UpdatedAt.IsZero() {
		out.UpdatedAt = ogen.NewOptDateTime(op.UpdatedAt.UTC())
	}
	if op.ToAccountID != 0 {
		out.ToAccountID = ogen.NewOptInt64(op.ToAccountID)
	}
	if op.CategoryID != 0 {
		out.CategoryID = ogen.NewOptInt64(op.CategoryID)
	}
	if op.OriginID != 0 {
		out.OriginID = ogen.NewOptInt64(op.OriginID)
	}
	if op.Time != "" {
		out.Time = ogen.NewOptString(op.Time)
	}
	if op.ImportID != 0 {
		out.ImportID = ogen.NewOptInt64(op.ImportID)
	}
	if op.MCC != "" {
		out.MCC = ogen.NewOptString(op.MCC)
	}
	if op.SourcePayee != "" {
		out.SourcePayee = ogen.NewOptString(op.SourcePayee)
	}
	return out
}

func fromOperationInput(req *ogen.OperationInput) (domain.OperationInput, error) {
	in := domain.OperationInput{
		Type:        domain.OpType(req.Type),
		AccountID:   req.AccountID,
		ToAccountID: req.ToAccountID.Or(0),
		CategoryID:  req.CategoryID.Or(0),
		Date:        req.Date,
		Time:        req.Time.Or(""),
		Payee:       req.Payee.Or(""),
		Note:        req.Note.Or(""),
		Tags:        req.Tags,
	}
	d, err := money.Parse(string(req.Amount))
	if err != nil {
		return in, fmt.Errorf("amount: invalid decimal: %w", errors.ErrInvalid)
	}
	in.Amount = d
	return in, nil
}

// fromOperationQuery returns the filter of req; its cursor and page size are not part
// of it.
func fromOperationQuery(req *ogen.OperationQuery) (domain.Filter, error) {
	f := domain.Filter{
		AccountID:  req.AccountID.Or(0),
		CategoryID: req.CategoryID.Or(0),
		Type:       domain.OpType(req.Type.Or("")),
		DateFrom:   req.DateFrom.Or(time.Time{}),
		DateTo:     req.DateTo.Or(time.Time{}),
		Query:      req.Query.Or(""),
	}
	if tag, ok := req.Tag.Get(); ok && tag != "" {
		f.Tags = []string{tag}
	}
	if v, ok := req.AmountMin.Get(); ok {
		d, err := money.Parse(string(v))
		if err != nil {
			return f, fmt.Errorf("amount_min: invalid decimal: %w", errors.ErrInvalid)
		}
		f.AmountMin = money.NullAmount{Amount: d, Valid: true}
	}
	if v, ok := req.AmountMax.Get(); ok {
		d, err := money.Parse(string(v))
		if err != nil {
			return f, fmt.Errorf("amount_max: invalid decimal: %w", errors.ErrInvalid)
		}
		f.AmountMax = money.NullAmount{Amount: d, Valid: true}
	}
	return f, nil
}

func toRule(r domain.Rule) ogen.Rule {
	out := ogen.Rule{
		ID:         r.ID,
		Stage:      ogen.RuleStage(r.Stage),
		Match:      ogen.RuleMatch(r.Match),
		Conditions: make([]ogen.RuleCondition, len(r.Conditions)),
		Actions:    make([]ogen.RuleAction, len(r.Actions)),
		Origin:     ogen.RuleOrigin(r.Origin),
		CreatedAt:  r.CreatedAt.UTC(),
	}
	for i, c := range r.Conditions {
		out.Conditions[i] = ogen.RuleCondition{
			Field: ogen.RuleField(c.Field), Op: ogen.RuleOp(c.Op), Values: append([]string{}, c.Values...),
		}
	}
	for i, a := range r.Actions {
		out.Actions[i] = ogen.RuleAction{Type: ogen.RuleActionType(a.Type), Value: ogen.NewOptString(a.Value)}
	}
	if !r.UpdatedAt.IsZero() {
		out.UpdatedAt = ogen.NewOptDateTime(r.UpdatedAt.UTC())
	}
	return out
}

func fromRuleInput(req *ogen.RuleInput) domain.RuleInput {
	in := domain.RuleInput{
		Stage:      domain.RuleStage(req.Stage.Or(ogen.RuleStageDefault)),
		Match:      domain.RuleMatch(req.Match.Or(ogen.RuleInputMatchAll)),
		Conditions: make([]domain.Condition, len(req.Conditions)),
		Actions:    make([]domain.Action, len(req.Actions)),
	}
	for i, c := range req.Conditions {
		in.Conditions[i] = domain.Condition{Field: domain.RuleField(c.Field), Op: domain.CondOp(c.Op), Values: c.Values}
	}
	for i, a := range req.Actions {
		in.Actions[i] = domain.Action{Type: domain.ActionType(a.Type), Value: a.Value.Or("")}
	}
	return in
}
